\1    /* PSE84_SKILL_PATCH vg_lite_wait: bounded wait (timeout in ms), report the status
     * bits in *value; the original looped forever and read *value unset. */
    uint32_t int_status = vg_lite_hal_peek(VG_LITE_INTR_STATUS);
    uint32_t waited_us = 0;
    uint32_t limit_us = ((timeout == 0U) || (timeout > 5000U)) ? 5000000U : (timeout * 1000U);
    while ((int_status == 0U) && (waited_us < limit_us)) {
        Cy_SysLib_DelayUs(1);
        waited_us++;
        int_status = vg_lite_hal_peek(VG_LITE_INTR_STATUS);
    }
    if (value != NULL) {
        *value = int_status & mask;
    }
    if (int_status == 0U) {
        return 0;
    }
    if (IS_AXI_BUS_ERR(int_status)) {
        vg_lite_bus_error_handler();
    }
    return 1;\2
